"""Anti-Gravity Mathematics: numerical demonstrations.

A *dependency DAG* models a formal library: vertices are theorems and an edge
``a -> b`` means "theorem ``a`` depends on (uses) theorem ``b``".  We work with
the transitive closure of the depends-on relation, so ``a `prec` b`` means
``a`` *transitively* depends on ``b``.

Core definitions mirrored from the formalization:

* ``weight(b)``      = number of theorems that depend on ``b``  (gravitational weight)
* ``len(b)``         = abstract proof length / cost of ``b``
* anti-gravity(b)    = weight(b) >= tau  AND  len(b) <= ell      (heavy yet cheap)

This script verifies, on concrete libraries, the three structural laws and the
refutation of the conjectured universal "10% law":

* weight_lt_of_dep            : a `prec` b  =>  weight(a) < weight(b)
* sum_weight_eq               : sum_b weight(b) = number of dependency pairs D
* exists_weight_ge_average    : some theorem has weight >= D / n
* fan construction            : a guaranteed anti-gravity theorem
* chain_antigravity_card      : chain of k+1 nodes has exactly k anti-gravity nodes
* discrete vs chain           : anti-gravity fraction ranges from 0 to k/(k+1) -> 1
"""

from __future__ import annotations

from typing import Dict, Iterable, List, Set, Tuple


# --------------------------------------------------------------------------- #
# Dependency DAG data structure                                               #
# --------------------------------------------------------------------------- #

class DependencyDAG:
    """A finite dependency DAG with proof lengths attached to each vertex.

    ``edges`` are *direct* dependencies ``(a, b)`` meaning "a depends on b".
    All weight computations use the transitive closure of these edges.
    """

    def __init__(
        self,
        vertices: Iterable[str],
        edges: Iterable[Tuple[str, str]],
        lengths: Dict[str, int] | None = None,
    ) -> None:
        self.vertices: List[str] = list(vertices)
        self.edges: List[Tuple[str, str]] = list(edges)
        self.lengths: Dict[str, int] = lengths or {v: 1 for v in self.vertices}
        self._succ: Dict[str, Set[str]] = self._build_succ()
        self._reach: Dict[str, Set[str]] = self._transitive_closure()

    def _build_succ(self) -> Dict[str, Set[str]]:
        succ: Dict[str, Set[str]] = {v: set() for v in self.vertices}
        for a, b in self.edges:
            succ[a].add(b)
        return succ

    def _transitive_closure(self) -> Dict[str, Set[str]]:
        """Per-vertex reachable set via depth-first search (efficient)."""
        reach: Dict[str, Set[str]] = {}

        def dfs(start: str) -> Set[str]:
            seen: Set[str] = set()
            stack: List[str] = list(self._succ[start])
            while stack:
                cur = stack.pop()
                if cur in seen:
                    continue
                seen.add(cur)
                stack.extend(self._succ[cur])
            return seen

        for v in self.vertices:
            reach[v] = dfs(v)
        return reach

    def depends_on(self, a: str, b: str) -> bool:
        """True iff ``a`` transitively depends on ``b`` (a `prec` b)."""
        return b in self._reach.get(a, ())

    def weight(self, b: str) -> int:
        """Gravitational weight: number of theorems depending on ``b``."""
        return sum(1 for a in self.vertices if b in self._reach[a])

    def proof_length(self, b: str) -> int:
        return self.lengths[b]

    def dependency_pairs(self) -> int:
        """D = number of transitive dependency pairs (edges of the closure)."""
        return sum(len(s) for s in self._reach.values())

    def is_antigravity(self, b: str, tau: int, ell: int) -> bool:
        """Heavy yet cheap: weight(b) >= tau and len(b) <= ell."""
        return self.weight(b) >= tau and self.proof_length(b) <= ell

    def antigravity_count(self, tau: int, ell: int) -> int:
        return sum(1 for b in self.vertices if self.is_antigravity(b, tau, ell))

    def antigravity_fraction(self, tau: int, ell: int) -> float:
        if not self.vertices:
            return 0.0
        return self.antigravity_count(tau, ell) / len(self.vertices)


# --------------------------------------------------------------------------- #
# Standard library constructions                                              #
# --------------------------------------------------------------------------- #

def discrete_library(n: int) -> DependencyDAG:
    """n theorems, no dependencies -> all weights 0."""
    return DependencyDAG([f"d{i}" for i in range(n)], [])


def chain_library(k: int, cost: int = 1) -> DependencyDAG:
    """t0 `prec` t1 `prec` ... `prec` tk  (k+1 vertices), constant proof cost."""
    verts = [f"t{i}" for i in range(k + 1)]
    edges = [(f"t{i}", f"t{i + 1}") for i in range(k)]  # ti depends on t(i+1)
    return DependencyDAG(verts, edges, {v: cost for v in verts})


def fan_library(n: int, root_cost: int = 1) -> DependencyDAG:
    """n leaves each depending on a single root r -> weight(r) = n."""
    verts = ["r"] + [f"a{i}" for i in range(n)]
    edges = [(f"a{i}", "r") for i in range(n)]
    lengths = {v: 1 for v in verts}
    lengths["r"] = root_cost
    return DependencyDAG(verts, edges, lengths)


