def check_weight_lt_of_dep(dag: DependencyDAG) -> bool:
    """Theorem weight_lt_of_dep: a `prec` b => weight(a) < weight(b)."""
    w = {v: dag.weight(v) for v in dag.vertices}
    for a in dag.vertices:
        for b in dag.vertices:
            if dag.depends_on(a, b) and not (w[a] < w[b]):
                return False
    return True


def check_sum_weight_eq(dag: DependencyDAG) -> bool:
    """Theorem sum_weight_eq: sum of weights = number of dependency pairs."""
    return sum(dag.weight(b) for b in dag.vertices) == dag.dependency_pairs()


